  ('f8bb33d0-ec23-5cae-afca-e00949b2b93f', 'c1437b0b-9d8a-50e6-b93b-6a826feaae34', 'Mango-Curry', 'curry', null, 'Cremiges Kokos-Curry mit frischer Mango: fruchtig, leicht scharf und in einer knappen halben Stunde auf dem Tisch.', 4, 25, 'main', 'Thailändisch', '{"schnell","scharf","meal prep"}', '[{"id":"258f56c2-d2ca-58d5-9dae-79fa1f3fd414","name":"mit Tofu","isDefault":true},{"id":"6f2a05d0-9ced-566b-b823-c7967e1b9c30","name":"mit Hähnchen","isDefault":false}]'::jsonb, '[{"id":"f6bc27e8-aa99-5fad-b73a-84ba496e032e","articleId":"f08f72c1-57d4-5306-b557-9add7b8a1bc6","name":"Kokosmilch","amount":{"text":"400 ml","qty":400,"unit":"ml"},"shoppingRule":"recipeAmount"},{"id":"9817e7b6-167a-560e-a67f-49a29541ba26","articleId":"73bdc55d-ef18-5b78-9f22-043ddb2c3d34","name":"Mango","amount":{"text":"1","qty":1},"shoppingRule":"recipeAmount"},{"id":"af79f7f8-8550-581c-98ac-0f7780128ad2","articleId":"25684a7f-5363-588e-b8c0-73b56c537f22","name":"Zwiebeln","amount":{"text":"1","qty":1},"shoppingRule":"recipeAmount"},{"id":"46384537-9bf1-5a72-bb35-98aaf88b9bf2","articleId":"5b8728a1-4c8b-503b-844d-0e9b9232eac8","name":"Knoblauch","amount":{"text":"2 Zehen","qty":2,"unit":"Zehe"},"shoppingRule":"count"},{"id":"71cdd427-fa51-5f36-af44-4fd1b3381e9b","articleId":"395bacf3-a18a-511a-8b70-83b0ae0d0a84","name":"Ingwer","amount":{"text":"20 g","qty":20,"unit":"g"},"shoppingRule":"count"},{"id":"c89e3959-cced-52ec-9398-ef9c1004030b","articleId":"a73be779-0425-53c3-88b3-36c44e2f485a","name":"Currypaste","amount":{"text":"2 EL","qty":2,"unit":"EL"},"shoppingRule":"count"},{"id":"d2e835c0-f916-5cf0-a585-f98cb34a0a25","articleId":"28fe1a90-b8e8-50d6-881c-ab922918fffa","name":"Reis","amount":{"text":"250 g","qty":250,"unit":"g"},"shoppingRule":"count"},{"id":"c15df1d3-8348-5784-b52a-0d23910dea2e","articleId":"70f3dd5e-824c-50d7-8551-9d81e721b751","name":"Kreuzkümmel","amount":{"text":"1 TL","qty":1,"unit":"TL"},"shoppingRule":"count"},{"id":"69401ed7-4559-57c4-9bd1-4df33fab0713","articleId":"6a2343fd-7120-582f-bb84-5224956cba29","name":"Limetten","amount":{"text":"1","qty":1},"shoppingRule":"recipeAmount"},{"id":"98f4855a-6e5f-57cc-bcaf-fb7fe58831e7","articleId":"9dce89d9-c0fc-59b5-ba22-8aafa607b1e5","name":"Koriander","amount":{"text":"½ Bund","qty":0.5,"unit":"Bund"},"shoppingRule":"count"},{"id":"c8eee70c-59b4-531c-aff0-5a21492ae59c","articleId":"f9182dcf-1443-5dc3-97f7-561aea69c0ee","name":"Salz","shoppingRule":"skip"},{"id":"f351329d-1db8-5830-8193-e0ad4cd89813","articleId":"36754bc9-43a0-525f-8551-b526965d9ce4","name":"Räuchertofu","amount":{"text":"400 g","qty":400,"unit":"g"},"variantId":"258f56c2-d2ca-58d5-9dae-79fa1f3fd414","shoppingRule":"recipeAmount"},{"id":"f46a98f0-c7e1-5783-999f-b71716efc3a9","articleId":"c576d001-2b8b-56a3-9eb2-b3491483b10e","name":"Hähnchenbrust","amount":{"text":"400 g","qty":400,"unit":"g"},"variantId":"6f2a05d0-9ced-566b-b823-c7967e1b9c30","shoppingRule":"recipeAmount"}]'::jsonb, '[{"id":"c58c1f3f-4ec1-5a50-a5c0-2967836c254b","text":"Reis nach Packungsangabe in Salzwasser garen.","timerMinutes":15},{"id":"4286b482-2c3a-56a0-97df-10dbc1a778b2","text":"Zwiebel, Knoblauch und Ingwer schälen und fein würfeln. Mango schälen, das Fruchtfleisch vom Kern schneiden und würfeln."},{"id":"4fbb2ad1-1a42-5b1d-a814-a6cfdfe4e876","text":"3 EL vom dicken Teil der Kokosmilch in einem Topf erhitzen. Zwiebel, Knoblauch und Ingwer darin glasig dünsten, Currypaste und Kreuzkümmel 1 Minute mitrösten. Restliche Kokosmilch angießen und 8 Minuten sanft köcheln lassen.","timerMinutes":8},{"id":"2491acaa-a1be-5ce7-a95f-440c22a32255","text":"Währenddessen den Räuchertofu würfeln, in einer beschichteten Pfanne rundum knusprig braten und ins Curry geben.","variantId":"258f56c2-d2ca-58d5-9dae-79fa1f3fd414"},{"id":"a1ea5451-4acc-5c1b-a81a-c1a5cbb21fee","text":"Währenddessen die Hähnchenbrust in mundgerechte Stücke schneiden, salzen und in einer beschichteten Pfanne rundum goldbraun braten, bis sie durchgegart ist. Ins Curry geben.","variantId":"6f2a05d0-9ced-566b-b823-c7967e1b9c30"},{"id":"9f3888b0-fcb2-51ec-bb7f-1a9db7c90d8b","text":"Mangowürfel unterheben und kurz heiß werden lassen. Mit Limettensaft und Salz abschmecken, mit gehacktem Koriander bestreuen und mit dem Reis servieren."}]'::jsonb, null, 'Beim nächsten Mal mehr Limette.', ((now() at time zone 'Europe/Berlin')::date - 1), 9, 'Starter', now() + make_interval(days => -40, secs => 0.000000)),
