"5b8728a1-4c8b-503b-844d-0e9b9232eac8","name":"Knoblauch","amount":{"text":"1 Zehe","qty":1,"unit":"Zehe"},"shoppingRule":"count","group":"Belag"},{"id":"da276b2c-ce8f-51ec-8958-2b559aded2c5","articleId":"888a752a-0895-5a2f-8085-0c400d3a07d3","name":"Oregano","amount":{"text":"1 TL","qty":1,"unit":"TL"},"shoppingRule":"count","group":"Belag"},{"id":"89c86546-f68d-5be1-8d1c-263ba585e8b1","articleId":"4d03ccde-ece8-593f-8345-f319d37f70bb","name":"Basilikum","amount":{"text":"½ Bund","qty":0.5,"unit":"Bund"},"shoppingRule":"count","group":"Belag"},{"id":"cce4f3ab-fd13-5c85-802b-5bcbb54a0119","articleId":"c269de1f-3a5a-5c4d-b823-8c2c3df2bd1e","name":"Pfeffer","shoppingRule":"skip","group":"Belag"}]'::jsonb, '[{"id":"7d9462b4-66f6-5e45-83a0-878fb3b68223","text":"Mehl, Trockenhefe, Zucker und Salz mischen. Lauwarmes Wasser und Olivenöl zugeben und alles 8 Minuten zu einem glatten Teig kneten. Abgedeckt an einem warmen Ort 45 Minuten gehen lassen.","timerMinutes":45},{"id":"e09d03e6-9e8a-5f01-946e-7c85553b95b0","text":"Backofen mit einem Blech auf 250 °C Ober-/Unterhitze vorheizen. Passierte Tomaten mit gepresstem Knoblauch, Oregano, Salz und Pfeffer verrühren."},{"id":"c6df6b84-7924-597f-babb-66c2eab48dff","text":"Teig halbieren und auf Backpapier zu zwei dünnen Fladen ausziehen. Mit der Sauce bestreichen und mit gezupftem Mozzarella belegen."},{"id":"38fe07fd-a34b-5906-b715-9b7c05f4b648","text":"Die Pizzen nacheinander samt Backpapier auf das heiße Blech ziehen und je 10 Minuten backen, bis der Rand Blasen wirft.","timerMinutes":10},{"id":"18d3de10-8bb2-5f94-bfd9-cc1f6e86240c","text":"Mit Basilikumblättern belegen und sofort servieren."}]'::jsonb, null, null, null, 0, 'Starter', now() + make_interval(days => -73, secs => -0.000011)),
