ticleId":"08074cfc-57b4-5670-8c16-0ab341ae9b64","name":"Muskatnuss","amount":{"text":"1 Prise","qty":1,"unit":"Prise"},"shoppingRule":"count"},{"id":"6a7bb019-96b3-5dcd-8841-954213557601","articleId":"4ca5d7e2-3305-566a-bfd5-a0d322d779c3","name":"Schnittlauch","amount":{"text":"½ Bund","qty":0.5,"unit":"Bund"},"shoppingRule":"count"},{"id":"5cfc41eb-cd58-591d-b066-ffba9898f207","articleId":"f9182dcf-1443-5dc3-97f7-561aea69c0ee","name":"Salz","shoppingRule":"skip"},{"id":"bc4c5f3c-edd7-58b5-aee3-fb968f662e4f","articleId":"c269de1f-3a5a-5c4d-b823-8c2c3df2bd1e","name":"Pfeffer","shoppingRule":"skip"},{"id":"02e7db2c-7349-5c7a-bbec-272924efaf96","articleId":"36754bc9-43a0-525f-8551-b526965d9ce4","name":"Räuchertofu","amount":{"text":"200 g","qty":200,"unit":"g"},"variantId":"a7962302-ef9d-5067-b5db-a41bd2328510","shoppingRule":"recipeAmount"},{"id":"a74793ff-0dac-5fc6-9895-b985634a90a9","articleId":"6b082d16-a8bc-54bd-9da7-40d2a170468c","name":"Rapsöl","amount":{"text":"1 EL","qty":1,"unit":"EL"},"variantId":"a7962302-ef9d-5067-b5db-a41bd2328510","shoppingRule":"count"},{"id":"4cc994e5-f56b-5eba-88a5-ee5e026bbc84","articleId":"34faa72f-555f-5958-bdbc-9f2ed924175c","name":"Wiener Würstchen","amount":{"text":"4","qty":4},"variantId":"253ddddf-d0b7-50bc-b0f8-868046ed72d2","shoppingRule":"recipeAmount"}]'::jsonb, '[{"id":"e9e425d5-254b-51a9-835a-ed1fcdee8b32","text":"Kartoffeln schälen und würfeln. Suppengrün putzen und klein schneiden, Zwiebel würfeln."},{"id":"6dec51cf-f44d-5f19-9a24-5724106e13fa","text":"Butter in einem großen Topf zerlassen, Zwiebel und Suppengrün 5 Minuten anschwitzen. Kartoffeln, Brühe, Lorbeerblätter und Majoran zugeben und 20 Minuten kochen, bis die Kartoffeln weich sind.","timerMinutes":20},{"id":"eb832267-2ec6-5c66-b765-9aaa23d530cb","text":"Lorbeerblätter entfernen. Die Suppe mit dem Kartoffelstampfer grob zerdrücken oder zur Hälfte pürieren, Sahne einrühren und mit Muskat, Salz und Pfeffer abschmecken."},{"id":"5486f962-56d6-5500-8a52-ca3f1d52d3c6","text":"Räuchertofu fein würfeln, im Rapsöl knusprig braten und über die Suppe streuen.","variantId":"a7962302-ef9d-5067-b5db-a41bd2328510"},{"id":"20b32803-7274-5546-8676-14752332c093","text":"Würstchen in Scheiben schneiden und 5 Minuten in der Suppe heiß werden lassen.","variantId":"253ddddf-d0b7-50bc-b0f8-868046ed72d2","timerMinutes":5},{"id":"34227ca8-e8d4-5f70-b25d-960474309cb9","text":"Mit Schnittlauchröllchen bestreut servieren."}]'::jsonb, null, null, ((now() at time zone 'Europe/Berlin')::date - 91), 1, 'Starter', now() + make_interval(days => -103, secs => -0.000021)),
  ('cda30407-85d9-5eef-8ce1-89cda2a216b2', 'c1437b0b-9d8a-50e6-b93b-6a826feaae34', 'Bircher Müsli', null, null, 'Über Nacht eingeweichte Haferflocken mit geriebenem Apfel, Heidelbeeren und gerösteten Haselnüssen.', 2, 10, 'breakfast', 'Schweizerisch', '{"meal prep","leicht","schnell"}', '[]'::jsonb, '[{"id":"66cc1a18-02f4-5d94-8518-d2f04868f984","articleId":"531e6a5c-2d32-531c-ab6c-85af8af41a8d","name":"Haferflocken","amount":{"text":"100 g","qty":100,"unit":"g"},"shoppingRule":"count"},{"id":"b307fc94-e569-525f-af28-4a7b887dfa37","articleId":"f132c4b9-c58b-5bac-9736-1b2033d02feb","name":"Milch","amount":{"text":"200 ml","qty":200,"unit":"ml"},"shoppingRule":"count"},{"id":"4eb88bfa-741e-5549-a366-a85d4c4ca3b2","articleId":"79467150-a370-54ea-8655-91562764af83","name":"Joghurt","amount":{"text":"150 g","qty":150,"unit":"g"},"shoppingRule":"count"},{"id":"4cd22f88-4bfc-5acd-b69a-44be4785f90d","articleId":"a3f44bcd-fe8f-5e19-b33a-3f9b6f174d2a","name":"Honig","amount":{"text":"1 EL","qty":1,"unit":"EL"},"shoppingRule":"count"},{"id":"3f008940-493e-57c9-88b7-c30f7121d1a0","articleId":"a3dda6cd-3932-55df-afc9-db2018065c32","name":"Rosinen","amount":{"text":"2 EL","qty":2,"unit":"EL"},"shoppingRule":"count"},{"id":"44e4ad4c-7551-5b28-bbe6-7b84dd8a8ca3","articleId":"2284e2ed-9945-52d4-965e-34d6deff1f83","name":"Zimt","amount":{"text":"1 Prise","qty":1,"unit":"Prise"},"shoppingRule":"count"},{"id":"1c67abc3-b59e-5ef8-beb8-2125043e38e2","articleId":"a26c4396-c26f-5d20-ad94-e355bc1e3fae","name":"Äpfel","amount":{"text":"1","qty":1},"shoppingRule":"recipeAmount"},{"id":"53cc8750-5c51-55c6-aa47-a0837e8a1df4","articleId":"0353f38d-e43b-5b50-b625-88572a265023","name":"Zitronen","amount":{"text":"½","qty":0.5},"shoppingRule":"count"},{"id":"7e17c8c0-22e7-56de-8c50-e55c94eb0718","articleId":"f33a2591-9dc2-5c61-bc77-b36cd0b92a2f","name":"Haselnüsse","amount":{"text":"30 g","qty":30,"unit":"g"},"shoppingRule":"count"},{"id":"25e5e6ac-e3a3-553c-866a-641d24183e91","articleId":"319ba6cc-d6fb-5470-8300-5fa5078a9c63","name":"Heidelbeeren","amount":{"text":"125 g","qty":125,"unit":"g"},"shoppingRule":"recipeAmount"}]'::jsonb, '[{"id":"f9c63533-57d1-5633-b284-a3908a79fb96","text":"Am Vorabend Haferflocken, Milch, Joghurt, Honig, Rosinen und Zimt verrühren und abgedeckt über Nacht in den Kühlschrank stellen."},{"id":"6875f4d4-e93c-5c60-8f8f-70f851b28869","text":"Am Morgen den Apfel mit Schale grob reiben, sofort mit Zitronensaft mischen und unter das Müsli heben."},{"id":"0becfcab-9e19-5535-ac9e-31d8eefabd75","text":"Haselnüsse grob hacken und in einer Pfanne ohne Fett kurz rösten."},{"id":"ff4c7aaf-a0c8-5d3b-9d86-f7eba3d079f5","text":"Müsli in zwei Schalen füllen und mit Heidelbeeren und Haselnüssen bestreuen. Ist es zu fest, einen Schuss Milch unterrühren."}]'::jsonb, '{"text":"Haferflocken über Nacht einweichen","hoursBefore":8}'::jsonb, null, ((now() at time zone 'Europe/Berlin')::date - 95), 4, 'Starter', now() + make_interval(days => -106, secs => -0.000022)),
  ('dbda237f-185e-5732-b7a2-f9b0cbd37318', 'c1437b0b-9d8a-50e6-b93b-6a826feaae34', 'Kaiserschmarrn', null, null, 'Luftig gebackener, zerrupfter Pfannkuchen mit Rosinen, Puderzucker und Apfelmus. Als Dessert für vier oder süßes Hauptgericht für zwei.', 4, 25, 'dessert', 'Österreichisch', '{"süß","kinder","klassiker"}', '[]'::jsonb, '[{"id":"ff808a6d-e28c-548e-bde8-aafbe9ee7362","articleId":"72021a11-3828-5ba7-9c75-4e82030f1deb","name":"Eier","amount":{"text":"4","qty":4},"shoppingRule":"count"},{"id":"50858f08-86c3-579d-b6e9-11fcdb7152e5","articleId":"a3e12834-4c68-5a49-85a2-157ddf6f4b1a","name":"Mehl","amount":{"text":"200 g","qty":200,"unit":"g"},"shoppingRule":"count"},{"id":"63b07277-aa61-5f97-89e7-ea71f17e1122","articleId":"f132c4b9-c58b-5bac-9736-1b2033d02feb","name":"Milch","amount":{"text":"300 ml","qty":300,"unit":"ml"},"shoppingRule":"count"},{"id":"c563f440-8cc1-5e0f-b56b-7e1ab585ca36","articleId":"89972a8e-10e6-5eea-8971-538cef84c7fd","name":"Zucker","amount":{"text":"2 EL","qty":2,"unit":"EL"},"shoppingRule":"count"},{"id":"7770e546-7e7a-5b66-a3dd-c897f6a89365","articleId":"4b61ceb9-215d-507e-a92b-9fd89204f6ee","name":"Vanillezucker","amount":{"text":"1 Packung","qty":1,"unit":"Packung"},"shoppingRule":"count"},{"id":"6b79b081-1d68-5f11-9bcb-fbc22db130ac","articleId":"f9182dcf-1443-5dc3-97f7-561aea69c0ee","name":"Salz","amount":{"text":"1 Prise","qty":1,"unit":"Prise"},"shoppingRule":"skip"},{"id":"e60eebd7-33a6-5833-9be8-f60661be0830","articleId":"5dfa57c9-1b9b-5e86-b209-baa9db37fec0","name":"Butter","amount":{"text":"40 g","qty":40,"unit":"g"},"shoppingRule":"count"},{"id":"6312983c-9028-5508-96a6-8af757eede14","articleId":"a3dda6cd-3932-55df-afc9-db2018065c32","name":"Rosinen","amount":{"text":"2 EL","qty":2,"unit":"EL"},"shoppingRule":"count"},{"id":"c41885d0-294b-5208-ad94-4da1c3d6695c","articleId":"3998f489-ac3b-5b11-bba6-da805f6fec42","name":"Puderzucker","amount":{"text":"1 EL","qty":1,"unit":"EL"},"shoppingRule":"count"},{"id":"b6b13740-a4a5-5203-b996-1a5f8c150744","articleId":"2f817bfc-eed5-5eb2-a189-3c3247fbb509","name":"Apfelmus","amount":{"text":"1 Glas","qty":1,"unit":"Glas"},"shoppingRule":"recipeAmount"}]'::jsonb, '[{"id":"1fa808e7-3c9f-58b0-bc12-55b581234173","text":"Eier trennen. Eigelb mit Milch, Mehl, Vanillezucker und Salz zu einem glatten Teig verrühren."},{"id":"5a0da5ff-aef1-5777-983a-d527ea58d8dd","text":"Eiweiß mit dem Zucker steif schlagen und locker unter den Teig heben."},{"id":"ebbc1806-ad67-5b23-b853-ff95e90b2393","text":"Die Hälfte der Butter in einer großen Pfanne aufschäumen lassen, den Teig hineingeben und die Rosinen darüberstreuen. Bei mittlerer Hitze 5 Minuten backen, bis die Unterseite goldbraun ist.","timerMinutes":5},{"id":"ba2f2f19-67e2-55dd-81e9-035249f8ea13","text":"Den Teig vierteln und wenden. Restliche Butter zugeben, 3 Minuten weiterbacken und dabei mit zwei Pfannenwendern in mundgerechte Stücke reißen.","timerMinutes":3},{"id":"ea10654f-9f07-5286-ba1b-fb532b725288","text":"Mit Puderzucker bestäuben und mit Apfelmus servieren."}]'::jsonb, null, null, null, 0, 'Starter', now() + make_interval(days => -109, secs => -0.000023));
